);

BEGIN TRY
    BEGIN TRANSACTION;

    -- 1. Inglés (2): SectionContent propia %ContentBody_0% (interna 1) (se reutiliza si el tipo ya la vincula)
    SET @L2_S1_Id = NULL;
    SELECT TOP (1) @L2_S1_Id = n.SectionContentID FROM dbo.NotificationSectionContent n INNER JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID WHERE n.NotificationTypeID = 334 AND (n.InternalSectionID = 1 AND sc.Languaje = 2 AND ((sc.Content IS NULL AND @L2_S1_Nuevo IS NULL) OR HASHBYTES('SHA2_256', CAST(sc.Content AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_S1_Nuevo AS VARCHAR(MAX))))) ORDER BY n.ID;
    IF @L2_S1_Id IS NULL
    BEGIN
        INSERT INTO dbo.SectionContent (Languaje, Content, Inactive)
        VALUES (2, @L2_S1_Nuevo, 0);
        SET @L2_S1_Id = SCOPE_IDENTITY();
        INSERT INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES ('INSERT', 'Masterdb.dbo.SectionContent',
                'DELETE FROM Masterdb.dbo.SectionContent WHERE SectionContentID = ' + CAST(@L2_S1_Id AS VARCHAR(10)) + ';', @L2_S1_Id, 2);
    END;

    -- 2. Inglés (2): NotificationTemplateLang (llave: tipo + Lang_id)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang WHERE NotificationTypeID = 334 AND Lang_id = 2)
        INSERT INTO dbo.NotificationTemplateLang
            (NotificationTypeID, Lang_id, DisclaimerTopID, DisclaimerBottomID, ContentID, [Subject], Attachement, StyleSection, Inactive, title, BaseStyle)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationTemplateLang',
