               inserted.NotificationTypeID, inserted.Lang_id
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (334, 2, @L2_DSup_Id, @L2_DInf_Id, 1, @L2_Subject, '', @L2_StyleSection, 0, @L2_Title, 2);

    -- 3. Inglés (2): vínculo %ContentBody_0% (interna 1) → propia (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 334 AND InternalSectionID = 1 AND SectionContentID = @L2_S1_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 2
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (334, 1, @L2_S1_Id);

    -- 4. Inglés (2): vínculo %ContentBottom_0% (interna 3) → compartida #34 (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 334 AND InternalSectionID = 3 AND SectionContentID = @L2_S3_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 2
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (334, 3, @L2_S3_Id);

    -- 5. Inglés (2): vínculo %ContentHeader_0% (interna 4) → compartida #3 (llave: tipo + sección interna + idioma de la SectionContent)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE NotificationTypeID = 334 AND InternalSectionID = 4 AND SectionContentID = @L2_S4_Id)
        INSERT INTO dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID)
        OUTPUT 'INSERT', 'Masterdb.dbo.NotificationSectionContent',
               'DELETE FROM Masterdb.dbo.NotificationSectionContent WHERE ID = ' + CAST(inserted.ID AS VARCHAR(10)) + ';',
               inserted.ID, 2
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        VALUES (334, 4, @L2_S4_Id);

    -- 6. Activar el formato por secciones (al final: si algo falla antes, el tipo sigue en Legacy)
    IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTypes WHERE NotificationTypeID = 334 AND BuildType = 1)
    BEGIN
        UPDATE dbo.NotificationTypes SET BuildType = 1
        OUTPUT 'UPDATE', 'Masterdb.dbo.NotificationTypes',
               'UPDATE Masterdb.dbo.NotificationTypes SET BuildType = ' + CAST(deleted.BuildType AS VARCHAR(10)) + ' WHERE NotificationTypeID = ' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ';',
               deleted.NotificationTypeID, NULL
        INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
        WHERE NotificationTypeID = 334 AND BuildType = 0;
        IF @@ROWCOUNT <> 1 THROW 50015, N'NotificationTypes 334: no estaba en BuildType = 0; no se aplicó nada.', 1;
    END;

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    -- La variable de tabla sobrevive al ROLLBACK: muestra lo que se intentó antes del error.
    SELECT 'ERROR: se hizo ROLLBACK' AS Estado, * FROM @Rollback_Backup_Table ORDER BY ID;
    THROW;
END CATCH;

