   ------------------------------------------------------------------------------------- */
-- Estado del tipo: toda fila suya que ya exista debe ser igual a la que deja el cambio (segunda corrida o deshacer).
IF NOT EXISTS (SELECT 1 FROM dbo.NotificationTypes WHERE NotificationTypeID = 334 AND BuildType IN (0, 1))
    THROW 50101, N'El tipo 334 no existe o su BuildType no es 0 (Legacy) ni 1 (por secciones).', 1;
IF EXISTS (SELECT 1 FROM dbo.NotificationTemplateLang l WHERE l.NotificationTypeID = 334
           AND CASE WHEN (l.NotificationTypeID = 334 AND l.Lang_id = 2 AND l.ContentID = 1 AND l.BaseStyle = 2 AND l.Inactive = 0 AND DATALENGTH(l.Attachement) = 0 AND ((l.[Subject] IS NULL AND @L2_Subject IS NULL) OR HASHBYTES('SHA2_256', CAST(l.[Subject] AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_Subject AS VARCHAR(MAX)))) AND ((l.StyleSection IS NULL AND @L2_StyleSection IS NULL) OR HASHBYTES('SHA2_256', CAST(l.StyleSection AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_StyleSection AS VARCHAR(MAX)))) AND ((l.title IS NULL AND @L2_Title IS NULL) OR HASHBYTES('SHA2_256', CAST(l.title AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_Title AS VARCHAR(MAX)))) AND l.DisclaimerTopID = @L2_DSup_Id AND l.DisclaimerBottomID = @L2_DInf_Id) THEN 1 ELSE 0 END = 0)
    THROW 50102, N'El tipo 334 tiene NotificationTemplateLang distinta de la del borrador (o de un idioma que el borrador no tiene): alguien la cambió después del script.', 1;
IF EXISTS (SELECT 1 FROM dbo.NotificationSectionContent n LEFT JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID
           WHERE n.NotificationTypeID = 334
             AND CASE WHEN (n.InternalSectionID = 1 AND sc.Languaje = 2 AND ((sc.Content IS NULL AND @L2_S1_Nuevo IS NULL) OR HASHBYTES('SHA2_256', CAST(sc.Content AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_S1_Nuevo AS VARCHAR(MAX))))) OR (n.InternalSectionID = 3 AND n.SectionContentID = @L2_S3_Id) OR (n.InternalSectionID = 4 AND n.SectionContentID = @L2_S4_Id) THEN 1 ELSE 0 END = 0)
    THROW 50103, N'El tipo 334 tiene vínculos en NotificationSectionContent distintos de los del borrador: alguien los cambió después del script.', 1;
IF EXISTS (SELECT 1 FROM dbo.NotificationSectionContent n LEFT JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID
           WHERE n.NotificationTypeID = 334 GROUP BY n.InternalSectionID, sc.Languaje HAVING COUNT(*) > 1)
    THROW 50104, N'El tipo 334 tiene más de un vínculo para la misma sección e idioma en NotificationSectionContent: revísalo a mano.', 1;

DECLARE @Rollback_Backup_Table TABLE (
     ID            INT IDENTITY(1,1)
    ,ServerName    VARCHAR(120) DEFAULT @@SERVERNAME
    ,ActionType    VARCHAR(50)
    ,TableName     VARCHAR(120)
    ,RollbackQuery NVARCHAR(MAX)
    ,AffectedID    INT
    ,LanguageID    INT
);

BEGIN TRY
    BEGIN TRANSACTION;

    -- 1. Volver a Legacy primero: así el envío deja de buscar la configuración por secciones
    UPDATE dbo.NotificationTypes SET BuildType = 0
    OUTPUT 'UPDATE', 'Masterdb.dbo.NotificationTypes',
           'UPDATE Masterdb.dbo.NotificationTypes SET BuildType = ' + CAST(deleted.BuildType AS VARCHAR(10)) + ' WHERE NotificationTypeID = ' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ';',
           deleted.NotificationTypeID, NULL
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE NotificationTypeID = 334 AND BuildType = 1;

    -- 2. Ubicar por llave natural las secciones propias y los disclaimers nuevos (nunca por un ID escrito a mano)
    SET @L2_S1_Id = NULL;
    SELECT TOP (1) @L2_S1_Id = n.SectionContentID FROM dbo.NotificationSectionContent n INNER JOIN dbo.SectionContent sc ON sc.SectionContentID = n.SectionContentID WHERE n.NotificationTypeID = 334 AND (n.InternalSectionID = 1 AND sc.Languaje = 2 AND ((sc.Content IS NULL AND @L2_S1_Nuevo IS NULL) OR HASHBYTES('SHA2_256', CAST(sc.Content AS VARCHAR(MAX))) = HASHBYTES('SHA2_256', CAST(@L2_S1_Nuevo AS VARCHAR(MAX))))) ORDER BY n.ID;

    -- 3. Vínculos de NotificationSectionContent
    DELETE FROM dbo.NotificationSectionContent
    OUTPUT 'DELETE', 'Masterdb.dbo.NotificationSectionContent',
           'INSERT INTO Masterdb.dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID) VALUES (' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ', ' + CAST(deleted.InternalSectionID AS VARCHAR(10)) + ', ' + CAST(deleted.SectionContentID AS VARCHAR(10)) + ');',
           deleted.ID, 2
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE NotificationTypeID = 334 AND InternalSectionID = 1 AND SectionContentID = @L2_S1_Id;
    DELETE FROM dbo.NotificationSectionContent
    OUTPUT 'DELETE', 'Masterdb.dbo.NotificationSectionContent',
           'INSERT INTO Masterdb.dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID) VALUES (' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ', ' + CAST(deleted.InternalSectionID AS VARCHAR(10)) + ', ' + CAST(deleted.SectionContentID AS VARCHAR(10)) + ');',
           deleted.ID, 2
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE NotificationTypeID = 334 AND InternalSectionID = 3 AND SectionContentID = @L2_S3_Id;
    DELETE FROM dbo.NotificationSectionContent
    OUTPUT 'DELETE', 'Masterdb.dbo.NotificationSectionContent',
           'INSERT INTO Masterdb.dbo.NotificationSectionContent (NotificationTypeID, InternalSectionID, SectionContentID) VALUES (' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ', ' + CAST(deleted.InternalSectionID AS VARCHAR(10)) + ', ' + CAST(deleted.SectionContentID AS VARCHAR(10)) + ');',
           deleted.ID, 2
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE NotificationTypeID = 334 AND InternalSectionID = 4 AND SectionContentID = @L2_S4_Id;

    -- 4. NotificationTemplateLang por idioma
    DELETE FROM dbo.NotificationTemplateLang
    OUTPUT 'DELETE', 'Masterdb.dbo.NotificationTemplateLang',
           '-- NotificationTemplateLang tipo ' + CAST(deleted.NotificationTypeID AS VARCHAR(10)) + ' idioma ' + CAST(deleted.Lang_id AS VARCHAR(10)) + ' borrada: para rehacerla, corre 111269_migracion334.sql.',
           deleted.NotificationTypeID, deleted.Lang_id
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE NotificationTypeID = 334 AND Lang_id IN (2);

    -- 5. SectionContent propias que ya nadie vincula
    DELETE FROM dbo.SectionContent
    OUTPUT 'DELETE', 'Masterdb.dbo.SectionContent',
           '-- SectionContentID ' + CAST(deleted.SectionContentID AS VARCHAR(10)) + ' borrado: para rehacerla, corre 111269_migracion334.sql (crea uno con otro ID).',
           deleted.SectionContentID, deleted.Languaje
    INTO @Rollback_Backup_Table (ActionType, TableName, RollbackQuery, AffectedID, LanguageID)
    WHERE SectionContentID = @L2_S1_Id
      AND NOT EXISTS (SELECT 1 FROM dbo.NotificationSectionContent WHERE SectionContentID = @L2_S1_Id);

    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    -- La variable de tabla sobrevive al ROLLBACK: muestra lo que se intentó antes del error.
    SELECT 'ERROR: se hizo ROLLBACK' AS Estado, * FROM @Rollback_Backup_Table ORDER BY ID;
    THROW;
END CATCH;

